window.MockEnglishQuestionBank = [
  {id:'m1-01',paper:1,no:1,section:'Vocabulary',stem:"Mark: It's ten to eight now. I'm so hungry.\nMary: There is a good _____ near around here. Let's go there.",options:['bookstore','bank','station','restaurant'],answer:3,explanation:'由 hungry 與 Let’s go there 可知是去餐廳。'},
  {id:'m1-02',paper:1,no:2,section:'Vocabulary',stem:"Tom: What's Emma doing now?\nLisa: She is making breakfast in the _____.",options:['bathroom','bedroom','kitchen','garage'],answer:2,explanation:'make breakfast 是在 kitchen（廚房）進行。'},
  {id:'m1-03',paper:1,no:3,section:'Vocabulary',stem:'Lisa: Where is the _____? I want to withdraw(提領) money.\nLinda: It is next to the Great Restaurant.',options:['bank','bakery','bookstore','department store'],answer:0,explanation:'withdraw money 是領錢，應到 bank。'},
  {id:'m1-04',paper:1,no:4,section:'Vocabulary',stem:'Fred: How _____ do you play the guitar?\nKay: Twice a week. Playing the guitar makes me relaxed.',options:['much','far','often','long'],answer:2,explanation:'Twice a week 是頻率，問頻率用 How often。'},
  {id:'m1-05',paper:1,no:5,section:'Vocabulary',stem:"Sarah: How about going to the movies this afternoon?\nVic: I'm _____ that I can't go with you. I have an interview.",options:['embarrassed','afraid','happy','hard-working'],answer:1,explanation:'be afraid that 表示「恐怕／很抱歉」。'},
  {id:'m1-06',paper:1,no:6,section:'Vocabulary',stem:'Judy: Can you do me a _____? Turn off the radio, please.\nEmma: Sure.',options:['envelope','weather','sport','favor'],answer:3,explanation:'do someone a favor 是「幫某人一個忙」。'},
  {id:'m1-07',paper:1,no:7,section:'Vocabulary',stem:"His apartment is near the MRT station. It's _____ for him.",options:['strange','convenient','fresh','low'],answer:1,explanation:'住處靠近捷運站，對他很 convenient（方便）。'},
  {id:'m1-08',paper:1,no:8,section:'Vocabulary',stem:"Don't go out at midnight, Dona. It's _____ .",options:['dangerous','interesting','lucky','expensive'],answer:0,explanation:'半夜不要外出，因為 dangerous（危險）。'},
  {id:'m1-09',paper:1,no:9,section:'Vocabulary',stem:'Kenny is not always early to school. He is _____ late.',options:['usually','sometimes','never','often'],answer:1,explanation:'not always 的意思接近 sometimes。'},
  {id:'m1-10',paper:1,no:10,section:'Vocabulary',stem:'Lisa: How much does a bag of cookies _____?\nSam: One hundred dollars.',options:['weigh','catch','cost','remember'],answer:2,explanation:'問價格用 How much does ... cost?。'},
  {id:'m1-11',paper:1,no:11,section:'Grammar',stem:'Alice: Where is your cousin, Molly?\nDavid: She _____ to Australia for five months.',options:['has moved','moved','is moving','moves'],answer:0,explanation:'for five months 表示持續一段時間，使用現在完成式 has moved。'},
  {id:'m1-12',paper:1,no:12,section:'Grammar',stem:'Paul: Who _____ you the good news?\nGrace: My younger brother did. Why?',options:['will tell','telling','tells','told'],answer:3,explanation:'回答 did，可知問句為過去式：Who told you ...?。'},
  {id:'m1-13',paper:1,no:13,section:'Grammar',stem:"Kelly was worried _____ she didn't prepare for her test last night.",options:['whether','although','after','because'],answer:3,explanation:'後句說明擔心的原因，使用 because。'},
  {id:'m1-14',paper:1,no:14,section:'Grammar',stem:'Ken is 180 cm tall. Sally is 160 cm tall. He is _____ taller than her.',options:['most','much','less','many'],answer:1,explanation:'much 可修飾比較級 taller。'},
  {id:'m1-15',paper:1,no:15,section:'Grammar',stem:'Rita will celebrate her birthday with Willy, _____?',options:['does she','will she',"won't she","won't they"],answer:2,explanation:'附加問句前句是 will，肯定句後面用 won’t she。'},
  {id:'m1-16',paper:1,no:16,section:'Grammar',stem:'Neil spent one hour _____ his apartment yesterday. He cleans it twice a week.',options:['to clean','cleans','cleaning','clean'],answer:2,explanation:'spend + 時間 + V-ing，故選 cleaning。'},
  {id:'m1-17',paper:1,no:17,section:'Grammar',stem:"If it _____ windy tomorrow, we won't go on a picnic at the park.",options:['will be','is',"won't be","doesn't"],answer:1,explanation:'假設句 if 子句用現在式，不用未來式。'},
  {id:'m1-18',paper:1,no:18,section:'Grammar',stem:'_____ your homework now. It is twenty to eight.',options:['Do','Doing','Does','To do'],answer:0,explanation:'祈使句以原形動詞開頭：Do your homework。'},
  {id:'m1-19',paper:1,no:19,section:'Grammar',stem:'The house _____ built in 1980. It looks very old and dirty.',options:['was','built','builds','has been built'],answer:0,explanation:'house 是被建造，且時間是 1980，使用 was built。'},
  {id:'m1-20',paper:1,no:20,section:'Grammar',stem:'How many spoons _____ there on the table?',options:['is there','are','are they','are there'],answer:3,explanation:'How many + 複數名詞搭配 are there。'},
  {id:'m1-21',paper:1,no:21,section:'Cloze-test',stem:'Sean: Can you recommend(推薦) any good dishes?\nWaitress: Sure. We are _____ our chicken noodles and desserts.\nSean: Good. I’d like to _____ chicken noodles.\nWaitress: Would you like something to drink, sir?\nSean: Yes. Give me _____ hot chocolate.\nWaitress: OK. Your order will be _____ in ten minutes.\nSean: Thank you.\n\n(21)',options:['famous for','interested in','sick of','afraid of'],answer:0,explanation:'be famous for 表示「以……聞名」。'},
  {id:'m1-22',paper:1,no:22,section:'Cloze-test',stem:'Sean: Can you recommend(推薦) any good dishes?\nWaitress: Sure. We are famous for our chicken noodles and desserts.\nSean: Good. I’d like to _____ chicken noodles.\nWaitress: Would you like something to drink, sir?\nSean: Yes. Give me a cup of hot chocolate.\nWaitress: OK. Your order will be ready in ten minutes.\nSean: Thank you.\n\n(22)',options:['remember','order','smell','paint'],answer:1,explanation:'在餐廳點餐用 order。'},
  {id:'m1-23',paper:1,no:23,section:'Cloze-test',stem:'Sean: Can you recommend(推薦) any good dishes?\nWaitress: Sure. We are famous for our chicken noodles and desserts.\nSean: Good. I’d like to order chicken noodles.\nWaitress: Would you like something to drink, sir?\nSean: Yes. Give me _____ hot chocolate.\nWaitress: OK. Your order will be ready in ten minutes.\nSean: Thank you.\n\n(23)',options:['a dozen of','a piece of','a cup of','a bar of'],answer:2,explanation:'熱巧克力以杯計量：a cup of hot chocolate。'},
  {id:'m1-24',paper:1,no:24,section:'Cloze-test',stem:'Sean: Can you recommend(推薦) any good dishes?\nWaitress: Sure. We are famous for our chicken noodles and desserts.\nSean: Good. I’d like to order chicken noodles.\nWaitress: Would you like something to drink, sir?\nSean: Yes. Give me a cup of hot chocolate.\nWaitress: OK. Your order will be _____ in ten minutes.\nSean: Thank you.\n\n(24)',options:['strange','dangerous','pretty','ready'],answer:3,explanation:'訂單十分鐘後會準備好，用 ready。'},
  {id:'m1-25',paper:1,no:25,section:'Cloze-test',stem:'There are some tips for a successful supermarket. First, the goods people want to buy for certain(確定) _____ on a higher place. People will try to find them out. (25)',options:['are put','put','putting','puts'],answer:0,explanation:'goods 為複數且是「被放置」，用被動式 are put。'},
  {id:'m1-26',paper:1,no:26,section:'Cloze-test',stem:'There are some tips for a successful supermarket. First, the goods people want to buy for certain are put on a higher place. People will try to find them out. _____ people stay longer in a supermarket, they may spend more money. Then, the owner puts bread, drinks and instant noodles on different shelves in the supermarket. (26)',options:['Although','If','Whether','Before'],answer:1,explanation:'條件句意為「如果待得更久，可能花更多錢」，選 If。'},
  {id:'m1-27',paper:1,no:27,section:'Cloze-test',stem:'There are some tips for a successful supermarket. First, the goods people want to buy for certain are put on a higher place. People will try to find them out. If people stay longer in a supermarket, they may _____ more money. Then, the owner puts bread, drinks and instant noodles on different shelves in the supermarket. (27)',options:['cost','take','buy','spend'],answer:3,explanation:'spend money 表示花錢。'},
  {id:'m1-28',paper:1,no:28,section:'Cloze-test',stem:'Kelly goes to the movies with her friends once a month. There are many types of movies, _____, comedy(喜劇片), action and horror(恐怖片). She doesn’t like horror movies because she is afraid of the dark. The theater is near the department store. After going to the movies, they may go shopping. (28)',options:['in case','so that','for example','no matter'],answer:2,explanation:'後方列舉電影種類，使用 for example。'},
  {id:'m1-29',paper:1,no:29,section:'Cloze-test',stem:'Kelly goes to the movies with her friends once a month. There are many types of movies, for example, comedy(喜劇片), action and horror(恐怖片). She doesn’t like horror movies because she _____ the dark. The theater is near the department store. After going to the movies, they may go shopping. (29)',options:['is afraid of','is happy with','is excited about','is good at'],answer:0,explanation:'害怕黑暗用 be afraid of。'},
  {id:'m1-30',paper:1,no:30,section:'Cloze-test',stem:'Kelly goes to the movies with her friends once a month. There are many types of movies, for example, comedy(喜劇片), action and horror(恐怖片). She doesn’t like horror movies because she is afraid of the dark. The theater is near the department store. After _____ to the movies, they may go shopping. (30)',options:['go','going','to go','gone'],answer:1,explanation:'介系詞 After 後接 V-ing，選 going。'},
  {id:'m1-31',paper:1,no:31,section:'Reading',stem:'[A]\nDear Lisa,\n\nHow is it going?\nWe haven’t seen each other since 2016. It has been a long time. I really miss you. How is your new life in New York(紐約)?\nSummer vacation is coming. I plan to take a trip to New York at the end of July. After talking with my elder brother, I will be staying at his place. It is just one block away from the A Happy Day. If you have time, we can have a delicious dinner there.\nI am really looking forward to seeing you. We will have a lot of fun.\n\nBest wishes,\nRose\nMay 30, 2018\n\nWhat do we know from the letter?',options:['This is a thank you letter.','Lisa invites Rose to New York.','Rose will be staying in a hotel.','Rose will go to New York in summer.'],answer:3,explanation:'Rose 計畫七月底前往紐約，七月是夏天。'},
  {id:'m1-32',paper:1,no:32,section:'Reading',stem:'[A] Rose 的信中提到：If you have time, we can have a delicious dinner there.\n\nBased on the letter, what is “A Happy Day”?',options:["It's a bookstore.","It's a bank.","It's a restaurant.","It's a post office."],answer:2,explanation:'信中說要在 A Happy Day 吃晚餐，所以是 restaurant。'},
  {id:'m1-33',paper:1,no:33,section:'Reading',stem:'[A]\nRose 寫信給 Lisa：We haven’t seen each other since 2016. 信件日期為 May 30, 2018。\n\nWhat is true about Rose?',options:["She hasn't seen Lisa for two years.",'She moves to New York.','She will go to New York in May.',"She doesn't know Lisa."],answer:0,explanation:'從 2016 到 2018，Rose 已兩年沒有見到 Lisa。'},
  {id:'m1-34',paper:1,no:34,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Name: Meg Brown</th></tr><tr><td>Date of Birth</td><td>Jan. 10, 1991</td></tr><tr><td>Contact information</td><td>E-mail: megbrownfff@happymail.com<br>cellphone: 0900-000-111</td></tr><tr><td>Educational background</td><td>123 Senior high school<br>Lucky University</td></tr><tr><td>Skills</td><td>English, Internet, MS Words</td></tr><tr><td>Experience</td><td>Waitress (2 years)<br>Clerk (2 years)</td></tr></table>',stem:'How many years of working experience does Meg have?',options:['She has two-year working experience.','She has three-year working experience.','She has four-year working experience.','She has five-year working experience.'],answer:2,explanation:'Waitress 2 years 加上 Clerk 2 years，共 4 年。'},
  {id:'m1-35',paper:1,no:35,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Meg Brown</th></tr><tr><td>Date of Birth</td><td>Jan. 10, 1991</td></tr><tr><td>Educational background</td><td>123 Senior high school<br>Lucky University</td></tr><tr><td>Skills</td><td>English, Internet, MS Words</td></tr><tr><td>Experience</td><td>Waitress (2 years)<br>Clerk (2 years)</td></tr></table>',stem:'What do we know from the form?',options:["Meg doesn't have any working experience.",'Meg is a high school student.','Meg was born in fall.','Meg is good at English.'],answer:3,explanation:'Skills 列出 English，因此可知她擅長英文。'},
  {id:'m1-36',paper:1,no:36,section:'Reading',stem:'[C]\nMom: You look so tired.\nKen: I slept late.\nMom: What time did you go to bed last night?\nKen: Ten to twelve. I prepared for my math, English and history tests.\nMom: You should study harder. You failed the math test last time.\nKen: OK. I will.\nMom: You are sleepy. I will make you a cup of coffee.\nKen: No, thank you. I will buy one on my way to school.\nMom: I can drive you to school.\nKen: No, thank you. I walk to school.\nMom: I see.\n\nKen went to bed at _____ last night.',options:['12:10','11:50','10:12','11:10'],answer:1,explanation:'Ten to twelve 是 11:50。'},
  {id:'m1-37',paper:1,no:37,section:'Reading',stem:'[C] Ken 說：「I walk to school.」\n\nHow does Ken go to school?',options:['He goes to school on foot.','He goes to school by bike.','His mother drives him to school.','He goes to school by taxi.'],answer:0,explanation:'walk to school 表示步行上學，即 on foot。'},
  {id:'m1-38',paper:1,no:38,section:'Reading',stem:'[C]\nKen 為數學、英文與歷史考試準備到很晚，並說隔天上學途中會買咖啡。\n\nWhich of the sentences is TRUE?',options:['Ken has a Chinese test today.','Ken will buy a cup of coffee after school.','Ken went to bed late last night.','Ken forgot to prepare for the test.'],answer:2,explanation:'對話一開始 Ken 說 I slept late，故選 C。'},
  {id:'m1-39',paper:1,no:39,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Willy’s</th></tr><tr><td>Open hours</td><td>11:00 a.m. ~ 9:00 p.m.<br>Sunday ~ Friday</td></tr><tr><td>Combo (套餐)</td><td>Hamburger + Fish Soup $120<br>Hamburger + Salad $110</td></tr><tr><td>Burgers</td><td>Chicken Burger $100<br>Hamburger $50<br>Cheeseburger $80</td></tr><tr><td>Soups</td><td>Fish Soup $80<br>Corn Soup $50</td></tr><tr><td>Drinks</td><td>Ice Tea $100<br>Coffee $120<br>Juice $80<br>Coke $50<br>Bottled water $30</td></tr></table>',stem:'Emma bought a hamburger, a fish soup and a cup of coffee for lunch. How much did she spend?',options:['Two hundred and fifty dollars.','Two hundred and forty dollars.','Two hundred dollars.','One hundred and seventy dollars.'],answer:1,explanation:'漢堡＋魚湯套餐是 $120，加咖啡 $120，共 $240。'},
  {id:'m1-40',paper:1,no:40,section:'Reading',table:'<table class="me-table"><tr><th>Willy’s</th></tr><tr><td>Open hours: 11:00 a.m. ~ 9:00 p.m.<br>Sunday ~ Friday</td></tr></table>',stem:'Which of the sentences is TRUE?',options:["Willy's is a bookstore.",'A cup of coffee is cheaper than bottled water.','It opens nine hours a day.','It is closed on Saturday.'],answer:3,explanation:'營業日為 Sunday ~ Friday，因此星期六不營業。'},
  {id:'m2-01',paper:2,no:1,section:'Vocabulary',stem:'Jill: _____ did you go to the movies yesterday?\nTed: By bus.',options:['Why','How','When','Where'],answer:1,explanation:'By bus 是交通方式，使用 How 詢問。'},
  {id:'m2-02',paper:2,no:2,section:'Vocabulary',stem:"Dad: Who is that man?\nJudy: I don't know. He is a _____ to me.",options:['stranger','bedroom','sunset','spoon'],answer:0,explanation:'不認識的人是 stranger。'},
  {id:'m2-03',paper:2,no:3,section:'Vocabulary',stem:'Tom: Which _____ does Emma live?\nBill: She lives in Taipei.',options:['country','street','bookstore','city'],answer:3,explanation:'Taipei 是 city。'},
  {id:'m2-04',paper:2,no:4,section:'Vocabulary',stem:"Sean: How is the _____ today?\nLisa: It's cloudy.",options:['weather','road','show','movie'],answer:0,explanation:'cloudy 描述天氣，故為 weather。'},
  {id:'m2-05',paper:2,no:5,section:'Vocabulary',stem:'Mark will go to the _____ to send Nacy a postcard this Friday.',options:['restaurant','fire station','post office','bank'],answer:2,explanation:'寄明信片要去 post office。'},
  {id:'m2-06',paper:2,no:6,section:'Vocabulary',stem:'Wendy plays basketball every day. She _____ plays it in the afternoon.',options:['always','often','sometimes','never'],answer:0,explanation:'every day 表示百分之百的頻率，選 always。'},
  {id:'m2-07',paper:2,no:7,section:'Vocabulary',stem:'Amy _____ her car to work every day.',options:['rides','gets','spends','drives'],answer:3,explanation:'開車是 drive a car。'},
  {id:'m2-08',paper:2,no:8,section:'Vocabulary',stem:"We haven't seen each other for a long time. Can I _____ a photo with you after dinner?",options:['win','take','open','load'],answer:1,explanation:'拍照用 take a photo。'},
  {id:'m2-09',paper:2,no:9,section:'Vocabulary',stem:"It is _____ for students to go to bed before 11 p.m. Don't stay up late.",options:['convenient','dangerous','important','funny'],answer:2,explanation:'不要熬夜，十一點前睡覺很 important。'},
  {id:'m2-10',paper:2,no:10,section:'Vocabulary',stem:'Willy forgot to do his math _____ yesterday. His teacher is angry.',options:['school','glove','shirt','homework'],answer:3,explanation:'do math homework 表示做數學作業。'},
  {id:'m2-11',paper:2,no:11,section:'Grammar',stem:'Helen: Where is Lisa?\nNeil: She _____ to the USA. She will come back Taiwan this summer.',options:['went','has gone','goes','has been'],answer:1,explanation:'人已去美國、尚未回來，用 has gone to。'},
  {id:'m2-12',paper:2,no:12,section:'Grammar',stem:'Meg: How _____ did you spend yesterday?\nTed: One thousand dollars, I guess.',options:['much','often','long','soon'],answer:0,explanation:'問花了多少錢使用 How much。'},
  {id:'m2-13',paper:2,no:13,section:'Grammar',stem:'_____ he is tired, he still cleans the house by himself.',options:['Whether','Although','After','Because'],answer:1,explanation:'前後有轉折，使用 Although。'},
  {id:'m2-14',paper:2,no:14,section:'Grammar',stem:'Remember _____ off the light before going out.',options:['turning','turn','to turn','turned'],answer:2,explanation:'remember to V 表示記得去做某事。'},
  {id:'m2-15',paper:2,no:15,section:'Grammar',stem:"Mark has moved to Seattle, _____?",options:["hasn't he",'will Mark',"didn't he",'did he'],answer:0,explanation:'現在完成式肯定句的附加問句用 hasn’t he。'},
  {id:'m2-16',paper:2,no:16,section:'Grammar',stem:"Emma practices _____ the piano four times a week. It's one of her hobbies.",options:['plays','playing','to play','play'],answer:1,explanation:'practice 後接 V-ing，選 playing。'},
  {id:'m2-17',paper:2,no:17,section:'Grammar',stem:'The girl _____ bag is purple looks very pretty and tall.',options:['that','which','who','whose'],answer:3,explanation:'表示「那個女孩的包包」，所有格關係代名詞用 whose。'},
  {id:'m2-18',paper:2,no:18,section:'Grammar',stem:'The interesting book _____ by Neill White. He is a famous writer.',options:['wrote','writes','was written','was writing'],answer:2,explanation:'書是被作者寫的，使用被動式 was written。'},
  {id:'m2-19',paper:2,no:19,section:'Grammar',stem:'Washing the dishes _____ tiring for me. I seldom do it.',options:['is','has','are','were'],answer:0,explanation:'動名詞片語 Washing the dishes 視為單數，使用 is。'},
  {id:'m2-20',paper:2,no:20,section:'Grammar',stem:'Kelly studies two times as _____ as he does. She is hard-working.',options:['harder','hardest','most hard','hard'],answer:3,explanation:'倍數比較使用「two times as + 原級 + as」，選 hard。'},
  {id:'m2-21',paper:2,no:21,section:'Cloze-test',stem:'Sean: Your birthday is coming. How will you _____ it?\nRita: I will hold a party with my friends this Friday night. Are you coming?\nLeon: I’d like to, but I can’t.\nRita: Why not?\nLeon: My friend, Ted, will visit me on Friday night. We will go to the movies.\nRita: Too bad.\nLeon: How about going to the party after the movie?\nLeon: Good. The night is still young.\n\n(21)',options:['draw','build','forget','celebrate'],answer:3,explanation:'慶祝生日用 celebrate。'},
  {id:'m2-22',paper:2,no:22,section:'Cloze-test',stem:'Leon: I’d like to, _____ I can’t. (22)',options:['and','but','or','however'],answer:1,explanation:'前後句意轉折，兩句間用 but。'},
  {id:'m2-23',paper:2,no:23,section:'Cloze-test',stem:'Leon: My friend, Ted, will _____ me on Friday night. We will go to the movies. (23)',options:['visit','remember','paint','turn'],answer:0,explanation:'朋友到訪使用 visit。'},
  {id:'m2-24',paper:2,no:24,section:'Cloze-test',stem:'Leon: How about going to the party _____ the movie? (24)',options:['for','when','after','as'],answer:2,explanation:'電影結束後去派對，用 after。'},
  {id:'m2-25',paper:2,no:25,section:'Cloze-test',stem:'Sheila Stone is one of the most _____ writers in the world. Many readers love her books. She is only 30 years old, but she has written about 40 novels (小說). In fact, she can write two books a year. Miss Stone is a productive (多產的) writer. That’s why she can make a lot of money. (25)',options:['stupid','famous','boring','dangerous'],answer:1,explanation:'很多讀者喜愛她的書，表示她是 famous。'},
  {id:'m2-26',paper:2,no:26,section:'Cloze-test',stem:'Sheila Stone is one of the most famous writers in the world. Many readers love her books. She is only 30 years old, but she _____ about 40 novels (小說). In fact, she can write two books a year. Miss Stone is a productive (多產的) writer. That’s why she can make a lot of money. (26)',options:['has written','writes','wrote','was written'],answer:0,explanation:'到目前為止已寫了約四十本小說，使用 has written。'},
  {id:'m2-27',paper:2,no:27,section:'Cloze-test',stem:'Sheila Stone is one of the most famous writers in the world. Many readers love her books. She is only 30 years old, but she has written about 40 novels (小說). In fact, she can write two books a year. Miss Stone is a productive (多產的) writer. That’s why she can _____ a lot of money. (27)',options:['cost','give','make','borrow'],answer:2,explanation:'賺錢使用 make money。'},
  {id:'m2-28',paper:2,no:28,section:'Cloze-test',stem:'What sports do you like the best? Basketball, _____ or tennis? I like tennis best. There are some reasons to play tennis. First, tennis is one of the healthiest activities (活動). Then, it will add knowledge to people’s life. The third, playing tennis is fun. (28)',options:['piano','dress','jogging','baseball'],answer:3,explanation:'Basketball、baseball、tennis 都是運動項目。'},
  {id:'m2-29',paper:2,no:29,section:'Cloze-test',stem:'What sports do you like the best? Basketball, baseball or tennis? I like tennis best. There are some _____ to play tennis. First, tennis is one of the healthiest activities (活動). Then, it will add knowledge to people’s life. The third, playing tennis is fun. (29)',options:['books','people','tips','reasons'],answer:3,explanation:'後文列出 First、Then、The third，是打網球的 reasons。'},
  {id:'m2-30',paper:2,no:30,section:'Cloze-test',stem:'What sports do you like the best? Basketball, baseball or tennis? I like tennis best. There are some reasons to play tennis. First, tennis is one of the healthiest activities (活動). Then, it will add _____ to people’s life. The third, playing tennis is fun. (30)',options:['years','weight','knowledge','money'],answer:0,explanation:'答案鍵為 A；依原題保留。'},
  {id:'m2-31',paper:2,no:31,section:'Reading',stem:'[A]\nPaul: What do you plan to do during winter vacation?\nJudy: I’d like to go camping, take a trip and read a lot of comic books.\nPaul: Where do you plan to take a trip?\nJudy: Seattle (西雅圖). My best friend, Gina, lives there. She works in a bookstore.\nPaul: Great. Are you staying in her place?\nJudy: Yes. It saves me a lot of money.\nPaul: Does she live in a house?\nJudy: No, she lives in the apartment. It’s just three blocks away from the bus station.\nPaul: It’s convenient.\nJudy: Yes. I don’t need to rent a car.\n\nWhat does Gina probably(有可能) do?',options:['A nurse.','A clerk.','A cook.','A police woman.'],answer:1,explanation:'Gina 在書店工作，最可能是 clerk。'},
  {id:'m2-32',paper:2,no:32,section:'Reading',stem:'[A] Judy 會住在朋友 Gina 的地方，而不是飯店。\n\nJudy can save money because _____.',options:['she works with Gina','she lives in a station',"she won't be staying in a hotel",'she sells her car'],answer:2,explanation:'住在朋友家就不需要付飯店住宿費。'},
  {id:'m2-33',paper:2,no:33,section:'Reading',stem:'[A] What is true about Judy?',options:['She works in Seattle.','She will rent a car in the USA.','Her friend, Gina, lives near the airport.','She plans to take a trip on her winter vacation.'],answer:3,explanation:'Judy 在對話一開始說冬季假期想旅行。'},
  {id:'m2-34',paper:2,no:34,section:'Reading',table:'<table class="me-table"><tr><th>Time</th><th>Emma’s schedule</th></tr><tr><td>09:00</td><td>Call Mr. Roberson</td></tr><tr><td>09:30</td><td>Have a meeting with Mr. Smith</td></tr><tr><td>11:00</td><td>Send an e-mail to Mrs. Brown</td></tr><tr><td>12:00</td><td>Have lunch with Meg</td></tr><tr><td>13:30</td><td>Buy an air ticket</td></tr><tr><td>14:00</td><td>Meeting</td></tr><tr><td>16:00</td><td>Make an appointment (預約) with a doctor</td></tr><tr><td>16:30</td><td>Type some paper</td></tr><tr><td>17:30</td><td>Check e-mails</td></tr><tr><td>19:00</td><td>Have dinner with Lisa at Uncle’s</td></tr></table>',stem:'Emma doesn’t have to _____ in the morning.',options:['buy an air ticket','send an e-mail','call Mr. Roberson','talk to Mr. Smith'],answer:0,explanation:'買機票安排在 13:30，非上午。'},
  {id:'m2-35',paper:2,no:35,section:'Reading',table:'<table class="me-table"><tr><th>Time</th><th>Emma’s schedule</th></tr><tr><td>09:30</td><td>Have a meeting with Mr. Smith</td></tr><tr><td>11:00</td><td>Send an e-mail to Mrs. Brown</td></tr><tr><td>14:00</td><td>Meeting</td></tr><tr><td>19:00</td><td>Have dinner with Lisa at Uncle’s</td></tr></table>',stem:'What do we know from the schedule?',options:['Emma works in a hospital.',"Emma doesn't have any meeting today.","Uncle's is a restaurant.",'Emma needs to e-mail Mrs. Brown in the afternoon.'],answer:2,explanation:'Emma 在 Uncle’s 吃晚餐，可推知 Uncle’s 是餐廳。'},
  {id:'m2-36',paper:2,no:36,section:'Reading',table:'<table class="me-table"><tr><th>Reason students go to bed late</th><th>Percentage</th></tr><tr><td>play games</td><td>15%</td></tr><tr><td>do homework</td><td>35%</td></tr><tr><td>watch TV</td><td>20%</td></tr><tr><td>read comic books</td><td>5%</td></tr><tr><td>study</td><td>25%</td></tr></table>',stem:'There are 120 students taking the survey. There are _____ people who go to bed late because they need to do their homework.',options:['20','35','42','25'],answer:2,explanation:'120 × 35% = 42。'},
  {id:'m2-37',paper:2,no:37,section:'Reading',table:'<table class="me-table"><tr><th>Reason students go to bed late</th><th>Percentage</th></tr><tr><td>play games</td><td>15%</td></tr><tr><td>do homework</td><td>35%</td></tr><tr><td>watch TV</td><td>20%</td></tr><tr><td>read comic books</td><td>5%</td></tr><tr><td>study</td><td>25%</td></tr></table>',stem:'Which is the most common reason why students go to bed late?',options:['Play games.','Do homework.','Watch TV.','Study.'],answer:1,explanation:'最高比例為 do homework 的 35%。'},
  {id:'m2-38',paper:2,no:38,section:'Reading',stem:'[D] Mark’s diary\nSep 15\nToday isn’t my day.\nI got up late, so I went to the office by taxi. I spent almost three hundred dollars on the transportation(交通), but I was still five minutes late. My boss looked angry. He told me not to be late again, or he will hire(雇用) a new waiter.\n\nWhy was Mark late on September 15?',options:['He got up late.','He went to work by taxi.','He missed the bus.','He lost his watch.'],answer:0,explanation:'日記直接寫 I got up late。'},
  {id:'m2-39',paper:2,no:39,section:'Reading',stem:'[D] Mark 的老闆說若再遲到會雇用 a new waiter。\n\nWhere does Mark work?',options:['In a bookstore.','In a supermarket.','In a restaurant.','In a hospital.'],answer:2,explanation:'waiter 是餐廳服務生，可推知在餐廳工作。'},
  {id:'m2-40',paper:2,no:40,section:'Reading',stem:'[D]\nSep 16\nToday’s Kelly’s birthday. I bought a ring for her. We have known each other for five years. She is a friendly and polite girl. I really like her. We celebrated her birthday at a restaurant. We had fun.\n\nWhich of the sentences is TRUE?',options:["Kelly is Mark's sister.",'Mark was happy on September 16th.','Kelly bought a ring for Mark.',"They celebrated Kelly's birthday on September 15th."],answer:1,explanation:'Mark 在日記中說 We had fun，可知九月十六日很愉快。'},
  {id:'m3-01',paper:3,no:1,section:'Vocabulary',stem:'Amy: I forgot to _____ my homework.\nNeil: Again? Mr. Smith will be mad.',options:['travel','prepare','shout','bring'],answer:3,explanation:'老師會生氣，可知 Amy 忘了 bring（帶）作業。'},
  {id:'m3-02',paper:3,no:2,section:'Vocabulary',stem:'Mom: Buy a birthday cake at a _____ on your way home.\nLily: OK. I will.',options:['bakery','bedroom','bank','garage'],answer:0,explanation:'買生日蛋糕要到 bakery。'},
  {id:'m3-03',paper:3,no:3,section:'Vocabulary',stem:"Ken: What's your favorite _____?\nEva: I like math.",options:['bank','tiger','place','subject'],answer:3,explanation:'math 是學科，故選 subject。'},
  {id:'m3-04',paper:3,no:4,section:'Vocabulary',stem:"Emma: What _____ is today?\nBill: It's Friday.",options:['month','day','date','time'],answer:1,explanation:'回答 Friday，問的是星期幾，使用 What day。'},
  {id:'m3-05',paper:3,no:5,section:'Vocabulary',stem:'His younger sister was a _____ student. She usually got good grades.',options:['embarrassed','afraid','hard-working','silly'],answer:2,explanation:'常得到好成績，表示她很 hard-working。'},
  {id:'m3-06',paper:3,no:6,section:'Vocabulary',stem:'Lisa _____ a lot. She looks very different.',options:['changed','won','flew','felt'],answer:0,explanation:'看起來很不一樣，表示她改變很多。'},
  {id:'m3-07',paper:3,no:7,section:'Vocabulary',stem:'Karry has moved to Korea _____ 2015. We really miss him.',options:['for','since','as','when'],answer:1,explanation:'since 後接起始時間點 2015。'},
  {id:'m3-08',paper:3,no:8,section:'Vocabulary',stem:'Mother’s Day is celebrated on the _____ Sunday in May.',options:['two','sleepy','second','dangerous'],answer:2,explanation:'母親節是五月的第二個星期日。'},
  {id:'m3-09',paper:3,no:9,section:'Vocabulary',stem:'I am very _____. Can you give me a bottle of water?',options:['thirsty','late','famous','angry'],answer:0,explanation:'想喝水表示 thirsty。'},
  {id:'m3-10',paper:3,no:10,section:'Vocabulary',stem:'Willy used to make a shopping _____ before going to the department store.',options:['center','space','habit','list'],answer:3,explanation:'購物前會列 shopping list。'},
  {id:'m3-11',paper:3,no:11,section:'Grammar',stem:'Can you stop _____ loudly? I need a quiet place to prepare for my history test.',options:['to sing','singing','sing','sings'],answer:1,explanation:'stop V-ing 表示停止正在做的事。'},
  {id:'m3-12',paper:3,no:12,section:'Grammar',stem:'Frank saw a girl and her cat _____ are playing on the playground.',options:['which','who','that','whom'],answer:2,explanation:'先行詞包含人與動物，關係代名詞用 that。'},
  {id:'m3-13',paper:3,no:13,section:'Grammar',stem:'Linda’s birthday is coming. Please ask her _____ she will hold the party or not.',options:['whether','if','after','because'],answer:0,explanation:'whether ... or not 是固定用法。'},
  {id:'m3-14',paper:3,no:14,section:'Grammar',stem:'Adam: Mr. Roberts used _____ the guitar after school.\nBeth: But he seldom plays it now.',options:['playing','to playing','play','to play'],answer:3,explanation:'used to + 原形動詞，表示以前習慣做某事。'},
  {id:'m3-15',paper:3,no:15,section:'Grammar',stem:'If I _____ you, I would go swimming with your friends.',options:['am','was','were','are'],answer:2,explanation:'與現在事實相反的假設語氣，be 動詞用 were。'},
  {id:'m3-16',paper:3,no:16,section:'Grammar',stem:'Fred: How much does the pink dress _____?\nJane: One thousand dollars.',options:['cost','take','pay','spend'],answer:0,explanation:'物品花多少錢用 cost。'},
  {id:'m3-17',paper:3,no:17,section:'Grammar',stem:'Kelly _____ a trip next week. She is excited about it.',options:['took','will take','takes','was taking'],answer:1,explanation:'next week 表未來，使用 will take。'},
  {id:'m3-18',paper:3,no:18,section:'Grammar',stem:'Tell me _____ last week.',options:['how much did he spend','he spent how much','how much he did spend','how much he spent'],answer:3,explanation:'間接問句使用陳述句語序。'},
  {id:'m3-19',paper:3,no:19,section:'Grammar',stem:"Roger is interested _____ collecting stamps. It's his hobby.",options:['at','with','in','about'],answer:2,explanation:'be interested in 是固定搭配。'},
  {id:'m3-20',paper:3,no:20,section:'Grammar',stem:'Helen: Where _____ you go yesterday?\nNeil: I went shopping with my roommate.',options:['do','did','are','will'],answer:1,explanation:'yesterday 表過去式，助動詞用 did。'},
  {id:'m3-21',paper:3,no:21,section:'Cloze-test',stem:'Clerk: Welcome to Happy Hotel. How may I help you?\nDolly: I have a reservation (預約) for tonight. I’d like to _____.\nClerk: And your _____, please?\nDolly: Dolly Cage.\nClerk: Mrs. Dolly Cage. OK. A room for two guests was _____ under your name. May I see your ID, please?\nDolly: Here it is.\nClerk: Thank you. I’ll have to _____ you five thousand dollars for the night. Do you have a credit card?\nDolly: Yes. Here’s my VISA.\n\n(21)',options:['check in','look up','get up','take over'],answer:0,explanation:'旅館訂房後辦理入住用 check in。'},
  {id:'m3-22',paper:3,no:22,section:'Cloze-test',stem:'Clerk: And your _____, please?\nDolly: Dolly Cage. (22)',options:['address','name','habit','number'],answer:1,explanation:'Dolly Cage 是姓名，故選 name。'},
  {id:'m3-23',paper:3,no:23,section:'Cloze-test',stem:'A room for two guests was _____ under your name. (23)',options:['bought','remembered','booked','touched'],answer:2,explanation:'旅館房間被預訂用 booked。'},
  {id:'m3-24',paper:3,no:24,section:'Cloze-test',stem:'I’ll have to _____ you five thousand dollars for the night. (24)',options:['pay','spend','cost','charge'],answer:3,explanation:'旅館向客人收費用 charge someone money。'},
  {id:'m3-25',paper:3,no:25,section:'Cloze-test',stem:'There are three people in Emily’s family. She doesn’t have _____, so she doesn’t know how to get along well with people. Because Emily is shy and quiet, she doesn’t have many friends. Vicky is one of her best friends. They usually have dinner together. Emily really likes Vicky since she helps her a lot. (25)',options:['brothers and sisters','cats and dogs','bikes and cars','drinks and meals'],answer:0,explanation:'家中三人且沒有兄弟姊妹，選 brothers and sisters。'},
  {id:'m3-26',paper:3,no:26,section:'Cloze-test',stem:'There are three people in Emily’s family. She doesn’t have brothers and sisters, so she doesn’t know how to _____ people. (26)',options:['laugh at','get along well with','take a break with','prepare for'],answer:1,explanation:'和人相處融洽用 get along well with。'},
  {id:'m3-27',paper:3,no:27,section:'Cloze-test',stem:'Because Emily is _____ and quiet, she doesn’t have many friends. (27)',options:['outgoing','funny','popular','shy'],answer:3,explanation:'與 quiet 並列、且朋友少，選 shy。'},
  {id:'m3-28',paper:3,no:28,section:'Cloze-test',stem:'What are your hobbies? Cooking, hiking, reading or stamp collecting? Ken developed (發展) a(n) _____ in painting after he visited a museum. He has learnt how to paint for three years. Besides, he took up singing as a hobby because he could sing well. How about you? (28)',options:['stranger','house','interest','stand'],answer:2,explanation:'develop an interest in 表示培養對……的興趣。'},
  {id:'m3-29',paper:3,no:29,section:'Cloze-test',stem:'Ken developed an interest in painting after he visited a museum. He has _____ how to paint for three years. (29)',options:['learnt','caught','cooked','drunk'],answer:0,explanation:'learn how to paint 表示學習如何畫畫。'},
  {id:'m3-30',paper:3,no:30,section:'Cloze-test',stem:'Besides, he took up singing _____ a hobby because he could sing well. (30)',options:['on','as','with','on'],answer:1,explanation:'take up A as a hobby 表示把 A 當作嗜好。'},
  {id:'m3-31',paper:3,no:31,section:'Reading',stem:'[A]\nCathy didn’t go to school today because she didn’t feel well. She caught a cold yesterday, so she stayed at home. Cathy’s been having a headache, runny nose, and cough.\nCathy saw a doctor in the morning. The doctor told her to take some medicine and drink more water. Her classmate called her after school, but she didn’t pick up the phone. She was taking a shower.\n\nWhy didn’t Cathy pick up the phone?',options:['She went out.','She was sleeping.','She argued with her classmate.','She was in the bathroom.'],answer:3,explanation:'她當時正在洗澡，故在浴室。'},
  {id:'m3-32',paper:3,no:32,section:'Reading',stem:'[A] What is true about Cathy?',options:['She is a student.','She had a fever yesterday.',"She didn't have a headache.",'She saw a doctor in the afternoon.'],answer:0,explanation:'文章明確說 Cathy 今天沒有去學校，可知她是學生。'},
  {id:'m3-33',paper:3,no:33,section:'Reading',table:'<table class="me-table"><tr><th></th><th>Sun.</th><th>Mon.</th><th>Tues.</th><th>Wed.</th><th>Thu.</th><th>Fri.</th><th>Sat.</th></tr><tr><td>a.m.</td><td>cloudy</td><td>rainy</td><td>windy</td><td>sunny</td><td>windy</td><td>rainy</td><td>cloudy</td></tr><tr><td>p.m.</td><td>windy</td><td>rainy</td><td>sunny</td><td>rainy</td><td>rainy</td><td>rainy</td><td>cloudy</td></tr></table>',stem:'Wendy plans to go on a picnic at the park. What day may she go?',options:['Thursday','Saturday','Monday','Tuesday'],answer:1,explanation:'Saturday 上午與下午皆為 cloudy，其他選項有雨或風。'},
  {id:'m3-34',paper:3,no:34,section:'Reading',table:'<table class="me-table"><tr><th></th><th>Sun.</th><th>Mon.</th><th>Tues.</th><th>Wed.</th><th>Thu.</th><th>Fri.</th><th>Sat.</th></tr><tr><td>a.m.</td><td>cloudy</td><td>rainy</td><td>windy</td><td>sunny</td><td>windy</td><td>rainy</td><td>cloudy</td></tr><tr><td>p.m.</td><td>windy</td><td>rainy</td><td>sunny</td><td>rainy</td><td>rainy</td><td>rainy</td><td>cloudy</td></tr></table>',stem:'What do we know from the weather forecast?',options:["It's windy on Saturday.",'It rains every day.','Friday is a good day to go swimming at the beach.','It is rainy most often.'],answer:3,explanation:'兩個時段中 rainy 出現最多次。'},
  {id:'m3-35',paper:3,no:35,section:'Reading',stem:'[C]\nBeth: What do you do now?\nKen: I work at Uncle Tim as a waiter.\nBeth: Do you like your job?\nKen: Yes. Working at Uncle Tim is a dream job for me because I like to drink coffee, and chat with people.\nBeth: How long have you been working at a coffee shop?\nKen: For almost two years. I feel great to be working there.\nBeth: Are you satisfied with the pay?\nKen: Yes. I am getting paid over thirty thousand dollars a month.\nBeth: Great. How about your boss?\nKen: Mr. Thomas is a friendly, polite and smart man. We all like him.\n\nBased on the dialogue, what is “Uncle Tim?”',options:["It's a bakery.","It's a bank.","It's a coffee shop.","It's a pet shop."],answer:2,explanation:'對話直接說 Ken 在 a coffee shop 工作。'},
  {id:'m3-36',paper:3,no:36,section:'Reading',stem:'[C] How does Ken think about his job?',options:["He thinks it's boring.",'He likes his job.','He feels tired.','He wants to quit.'],answer:1,explanation:'Ken 說這是 dream job，且 feel great。'},
  {id:'m3-37',paper:3,no:37,section:'Reading',stem:'[C] Which of the sentences is TRUE?',options:['Ken is tired of Mr. Thomas.','Ken has been working at Uncle Tim for one year.','Ken is happy with his pay.','Ken likes to drink juice.'],answer:2,explanation:'Ken 對薪水回答 Yes，且每月收入超過三萬元。'},
  {id:'m3-38',paper:3,no:38,section:'Reading',table:'<table class="me-table"><tr><th colspan="3">Happy Land — Less Is More</th></tr><tr><td>Monday ~ Saturday</td><td colspan="2">11:00~21:00</td></tr><tr><td colspan="3">03/31/2018　20:15:58</td></tr><tr><th>Item</th><th>QTY.</th><th>Price</th></tr><tr><td>Notebooks</td><td>2</td><td>$100</td></tr><tr><td>Pen</td><td>1</td><td>$40</td></tr><tr><td>Book</td><td>1</td><td>$400</td></tr><tr><td>Erasers</td><td>2</td><td>$60</td></tr><tr><td>Magazine</td><td>1</td><td>$200</td></tr><tr><th>TOTAL</th><th>7</th><th>$800</th></tr></table>',stem:'What is “Happy Land?”',options:['A post office.','A bookstore.','A bakery.','A restaurant.'],answer:1,explanation:'收據出售筆記本、書、雜誌等，為 bookstore。'},
  {id:'m3-39',paper:3,no:39,section:'Reading',table:'<table class="me-table"><tr><th>Item</th><th>QTY.</th></tr><tr><td>Notebooks</td><td>2</td></tr><tr><td>Pen</td><td>1</td></tr><tr><td>Book</td><td>1</td></tr><tr><td>Erasers</td><td>2</td></tr><tr><td>Magazine</td><td>1</td></tr></table>',stem:'What didn’t Shelly buy?',options:["She didn't buy a ruler.","She didn't buy a book.","She didn't buy a magazine.","She didn't buy a pen."],answer:0,explanation:'收據列有書、雜誌與筆，沒有 ruler。'},
  {id:'m3-40',paper:3,no:40,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Happy Land</th></tr><tr><td>Open</td><td>Monday ~ Saturday, 11:00~21:00</td></tr><tr><td>Erasers</td><td>2 for $60</td></tr><tr><td>Books</td><td>1</td></tr></table>',stem:'Which of the sentences is TRUE?',options:['Happy Land opens every day.','Shelly went shopping in the afternoon.','An eraser cost sixty dollars.','Shelly bought only one book.'],answer:3,explanation:'收據中 Book 的數量為 1；其他選項與營業日、時間或單價不符。'}
,
  {id:'m4-01',paper:4,no:1,section:'Vocabulary',stem:"Sam: What date is today?\nBeth: I don't know. Let me check the _____.",options:['bank','restaurant','station','calendar'],answer:3,explanation:'A calendar shows the date.'},
  {id:'m4-02',paper:4,no:2,section:'Vocabulary',stem:"Helen: I don't like vegetables.\nSean: Why not? They are good for your _____.",options:['health','room','price','calendar'],answer:0,explanation:'Vegetables are good for your health.'},
  {id:'m4-03',paper:4,no:3,section:'Vocabulary',stem:"Can you turn on the light for me? It's _____ in the living room.",options:['bright','dark','hungry','useful'],answer:1,explanation:'If a light needs to be turned on, the room is dark.'},
  {id:'m4-04',paper:4,no:4,section:'Vocabulary',stem:"The man can't see anything because he is _____.",options:['happy','afraid','blind','thoughtful'],answer:2,explanation:'A blind person cannot see.'},
  {id:'m4-05',paper:4,no:5,section:'Vocabulary',stem:"Vic: The jacket cost me seven thousand dollars.\nSue: It's very _____.",options:['hard-working','yummy','wet','expensive'],answer:3,explanation:'Seven thousand dollars is expensive for a jacket.'},
  {id:'m4-06',paper:4,no:6,section:'Vocabulary',stem:"It's _____ tomorrow. How about going to the beach?",options:['sunny','snowy','funny','favorite'],answer:0,explanation:'Sunny weather is suitable for going to the beach.'},
  {id:'m4-07',paper:4,no:7,section:'Vocabulary',stem:'The supermarket near my school is having a big _____. A bottle of grape juice is only 15 dollars.',options:['forest','sale','dictionary','refrigerator'],answer:1,explanation:'Low prices at a store mean it is having a sale.'},
  {id:'m4-08',paper:4,no:8,section:'Vocabulary',stem:'Neil usually _____ the piano after school.',options:['pretends','hits','turns','plays'],answer:3,explanation:'We say play the piano.'},
  {id:'m4-09',paper:4,no:9,section:'Vocabulary',stem:'Helen is a _____ teacher. Many students like her.',options:['angry','humid','popular','terrible'],answer:2,explanation:'A teacher many students like is popular.'},
  {id:'m4-10',paper:4,no:10,section:'Vocabulary',stem:"Kelly went to the party last night. She didn't go home _____ eleven.",options:['with','around','until','without'],answer:2,explanation:'The pattern is not ... until + time.'},
  {id:'m4-11',paper:4,no:11,section:'Grammar',stem:'Emma: Who _____ over there?\nNeil: My new neighbor is.',options:['is standing','stood','stands','standing'],answer:0,explanation:'The question needs “Who is standing ...?”; the answer supplies “is.”'},
  {id:'m4-12',paper:4,no:12,section:'Grammar',stem:'Emma: Will Mr. Jordan go hiking next week?\nSean: Yes, he _____.',options:['is','will','does','was'],answer:1,explanation:'A yes/no question with will is answered with will.'},
  {id:'m4-13',paper:4,no:13,section:'Grammar',stem:'He looked angry _____ he heard the bad news.',options:['whether','when','before','although'],answer:1,explanation:'“When” connects the time he heard the news with his reaction.'},
  {id:'m4-14',paper:4,no:14,section:'Grammar',stem:'Who is the smartest, Mark, Jenny _____ Vicky?',options:['but','so','and','or'],answer:3,explanation:'Use “or” when choosing among alternatives in a question.'},
  {id:'m4-15',paper:4,no:15,section:'Grammar',stem:'_____ your homework now, or your father will be mad.',options:['Do','Doing','To do','Does'],answer:0,explanation:'An imperative sentence begins with the base verb: Do.'},
  {id:'m4-16',paper:4,no:16,section:'Grammar',stem:"Beth won't clean her room tomorrow and her sister _____.",options:["doesn't, either",'will, too',"won't, either",'does, too'],answer:2,explanation:'For a negative future statement, use “won’t, either.”'},
  {id:'m4-17',paper:4,no:17,section:'Grammar',stem:"Kelly was _____ her grades because she didn't prepare for the test.",options:['tired of','excited about','bored with','worried about'],answer:3,explanation:'Not preparing for a test can make someone worried about grades.'},
  {id:'m4-18',paper:4,no:18,section:'Grammar',stem:'Allen had a car accident this morning. He _____ to the hospital.',options:['is sent','was sending','sent','was sent'],answer:3,explanation:'He received the action in the past, so use passive voice: was sent.'},
  {id:'m4-19',paper:4,no:19,section:'Grammar',stem:'Meg is _____ girl in the office.',options:['most beautiful','more beautiful','the most beautiful','beautiful'],answer:2,explanation:'Use “the most beautiful” for the superlative comparison in the office.'},
  {id:'m4-20',paper:4,no:20,section:'Grammar',stem:'Dora is used to _____ to music when she does her homework.',options:['listening','listen','listened','listens'],answer:0,explanation:'Be used to is followed by a noun or gerund, so “listening.”'},
  {id:'m4-21',paper:4,no:21,section:'Cloze-test',stem:'[A]\nClerk: May I help you?\nLisa: Yes. I am _____ some hats.\nClerk: All our hats are in this section. How about this one?\nLisa: It looks nice. How much is it?\nClerk: It\'s five hundred dollars.\nLisa: OK. I will take it.\nClerk: Is there anything else I can get for you?\nLisa: No. Thank you.',options:['good at','glad at','popular with','interested in'],answer:3,explanation:'“Be interested in” means to want to know about or buy something.'},
  {id:'m4-22',paper:4,no:22,section:'Cloze-test',stem:'[A] Clerk: All our hats are in this section. _____ this one?',options:['How often','How about','How much','How long'],answer:1,explanation:'“How about this one?” is a suggestion.'},
  {id:'m4-23',paper:4,no:23,section:'Cloze-test',stem:'[A] Lisa: It looks nice. _____?',options:['How much is it','How old are you','How often do you go shopping','How tall is he'],answer:0,explanation:'The clerk answers with a price, so Lisa asks “How much is it?”'},
  {id:'m4-24',paper:4,no:24,section:'Cloze-test',stem:'[A] Clerk: Is there _____ else I can get for you?',options:['everything','nothing','thing','anything'],answer:3,explanation:'Questions commonly use “anything”: Is there anything else ...?'},
  {id:'m4-25',paper:4,no:25,section:'Cloze-test',stem:'[B]\nMolly had a bad day. She forgot _____ her homework and argued with her classmate, Lucy. She just wanted to take a rest and relax after school. Her mother asked her to mop the floor for her. Molly refused to do it, so her mother was not happy with her answer.',options:['bringing','bring','to bring','brought'],answer:2,explanation:'The pattern is forget to + verb: forgot to bring.'},
  {id:'m4-26',paper:4,no:26,section:'Cloze-test',stem:'[B] Molly just wanted to take a _____ and relax after school.',options:['picture','rest','joke','painting'],answer:1,explanation:'The fixed expression is take a rest.'},
  {id:'m4-27',paper:4,no:27,section:'Cloze-test',stem:'[B] Molly refused to do it, so her mother was not _____ with her answer.',options:['happy','sad','excited','tired'],answer:0,explanation:'Her mother was not happy with Molly’s refusal.'},
  {id:'m4-28',paper:4,no:28,section:'Cloze-test',stem:'[C]\nFranks was not _____ his classmates, so he tried to solve the problem. Frank asked one of his classmates, Kelly. She advised him to be more friendly. Besides, she told Frank not to look serious when talking to people. Frank nodded his head.',options:['tired of','surprised at','worried about','popular with'],answer:3,explanation:'The problem is that Frank was not popular with his classmates.'},
  {id:'m4-29',paper:4,no:29,section:'Cloze-test',stem:'[C] Frank asked one _____ his classmates, Kelly.',options:['at','of','for','with'],answer:1,explanation:'The correct phrase is one of + plural noun.'},
  {id:'m4-30',paper:4,no:30,section:'Cloze-test',stem:'[C] _____, she told Frank not to look serious when talking to people.',options:['Beside','In addition to','Except for','Besides'],answer:3,explanation:'“Besides,” adds another piece of advice.'},
  {id:'m4-31',paper:4,no:31,section:'Reading',stem:'[A]\nAdam and Roger worked in the same company. Adam was more popular than Roger because he was friendly and humorous. Roger often had a long face, so he didn\'t get along well with his co-workers. One day, Roger asked his boss, “What are the chances of getting a raise this year?” His boss told him the chances are slim. Roger was unhappy and left the office.\n\nWhat does “long face” mean?',options:['Unhappy','Excited','Happy','Pretty'],answer:0,explanation:'The passage explains that Roger had a long face and did not get along with coworkers; it means unhappy.'},
  {id:'m4-32',paper:4,no:32,section:'Reading',stem:'[A] What is true about Adam?',options:["He didn't get along well with his co-workers.",'He was the boss.','He was friendly.','He often had long face.'],answer:2,explanation:'The passage directly says Adam was friendly and humorous.'},
  {id:'m4-33',paper:4,no:33,section:'Reading',stem:'[A] Why did Roger look unhappy after talking to his boss?',options:['His boss shouted at him.','He may not get a raise.','He caught a cold.','He was fired.'],answer:1,explanation:'His boss said the chances of getting a raise were slim.'},
  {id:'m4-34',paper:4,no:34,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Lucky Store</th></tr><tr><td>Monday-Saturday</td><td>11:00~22:00</td></tr><tr><td>Sunday</td><td>11:00~18:00</td></tr><tr><th colspan="2">May 1st ~ May 14th<br><em>We Have a Big Sale.</em></th></tr><tr><td>Skirt</td><td>10% off</td></tr><tr><td>Jacket</td><td>30% off</td></tr><tr><td>Sweater</td><td>50% off</td></tr><tr><td>Pants</td><td>30% off</td></tr><tr><td>Shirt</td><td>30% off</td></tr><tr><td>Coat</td><td>20% off</td></tr><tr><td>Dress</td><td>30% off</td></tr><tr><td>Hat</td><td>20% off</td></tr><tr><th colspan="2">Special offers: Buy one and get one free on May 12th.<br><em>Don\'t miss the chance.</em></th></tr></table>',stem:'What is “Lucky Store”?',options:["It's a bookstore.","It's a supermarket.","It's a restaurant.","It's a clothing store."],answer:3,explanation:'The ad lists clothing such as skirts, jackets, sweaters, and dresses.'},
  {id:'m4-35',paper:4,no:35,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Lucky Store</th></tr><tr><td>Sale dates</td><td>May 1st ~ May 14th</td></tr><tr><td>Special offer</td><td>Buy one and get one free on May 12th.</td></tr><tr><td>Examples</td><td>Skirt 10% off; Sweater 50% off; Hat 20% off</td></tr></table>',stem:'What do we know from the ad?',options:['The store is having a sale.','The store will be closed on May 12th.','You can buy books in this store.','Everything is 20% off in this store.'],answer:0,explanation:'The advertisement says “We Have a Big Sale.”'},
  {id:'m4-36',paper:4,no:36,section:'Reading',table:'<table class="me-table"><tr><th>Day</th><th>Hours</th></tr><tr><td>Monday-Saturday</td><td>11:00~22:00</td></tr><tr><td>Sunday</td><td>11:00~18:00</td></tr></table>',stem:'It opens seven hours on _____.',options:['Saturday','Sunday','Monday','Tuesday'],answer:1,explanation:'Sunday hours are 11:00 to 18:00, which is seven hours.'},
  {id:'m4-37',paper:4,no:37,section:'Reading',table:'<table class="me-table"><tr><th>Lucky Store sale</th></tr><tr><td>May 1st ~ May 14th</td></tr><tr><td>Hat: 20% off</td></tr><tr><td>Buy one and get one free: May 12th</td></tr></table>',stem:'Which of the sentences is TRUE?',options:['The sale will last two weeks.','It opens six days a week.','Hats are not on sale.','You can buy and get one free on May 14th.'],answer:0,explanation:'May 1st through May 14th is two weeks.'},
  {id:'m4-38',paper:4,no:38,section:'Reading',stem:"[C]\nThere are some tips for how to stop rumors. Please read it carefully.\nAt first, try to prove that it's not true. Find out some truth and prove it.\nThe second, don't show them how much you care. If you care too much about rumors, you will be unhappy.\nThen, you shouldn't play dumb. When people gossip (八卦) about you, you should be stronger.\nFinally, don't be afraid of rumors.\n\nHow many tips are there in the article?",options:['One','Two','Three','Four'],answer:3,explanation:'The article gives four tips: At first, The second, Then, and Finally.'},
  {id:'m4-39',paper:4,no:39,section:'Reading',stem:'[C] What is the article mainly about?',options:["Don't talk behind my back.",'How to do to stop rumors?','Nobody is perfect.','Care about your friends.'],answer:1,explanation:'The opening sentence says these are tips for how to stop rumors.'},
  {id:'m4-40',paper:4,no:40,section:'Reading',stem:"[C] Which of the sentences is TRUE?",options:["You shouldn't be afraid of rumors.",'You should care about rumors more.','If you care about rumors, you will be stronger.','When people talk about you, you should leave.'],answer:0,explanation:'The final tip says not to be afraid of rumors.'}
,
  {id:'m5-01',paper:5,no:1,section:'Vocabulary',stem:"Meg is poor at math. I have taught her many times and she still can't _____ it.",options:['celebrate','save','understand','lead'],answer:2,explanation:'If Meg is poor at math, she cannot understand it.'},
  {id:'m5-02',paper:5,no:2,section:'Vocabulary',stem:'Helen is a _____ teacher. Many students like her.',options:['angry','humid','popular','terrible'],answer:2,explanation:'A teacher liked by many students is popular.'},
  {id:'m5-03',paper:5,no:3,section:'Vocabulary',stem:'She walked to the _____ and pulled out some ice cream.',options:['oven','sofa','bottle','refrigerator'],answer:3,explanation:'Ice cream is kept in a refrigerator.'},
  {id:'m5-04',paper:5,no:4,section:'Vocabulary',stem:'Kenny _____ a day to clean his apartment. He was very tired.',options:['paid','spent','cost','invited'],answer:1,explanation:'We spend time doing something.'},
  {id:'m5-05',paper:5,no:5,section:'Vocabulary',stem:"It's cold today. Put on your _____ before you go out.",options:['jacket','shorts','ring','light'],answer:0,explanation:'A jacket keeps you warm in cold weather.'},
  {id:'m5-06',paper:5,no:6,section:'Vocabulary',stem:'Emma: What does “homestay” mean?\nKen: You can look it up in the _____.',options:['dictionary','weather','place','favor'],answer:0,explanation:'Use a dictionary to look up the meaning of a word.'},
  {id:'m5-07',paper:5,no:7,section:'Vocabulary',stem:'Please read the _____ on the blackboard.',options:['trash','convenience','classroom','sentence'],answer:3,explanation:'A sentence can be written and read on a blackboard.'},
  {id:'m5-08',paper:5,no:8,section:'Vocabulary',stem:"You should listen to the teacher _____ in class. Don't fall asleep again.",options:['sadly','quickly','carefully','badly'],answer:2,explanation:'Students should listen carefully in class.'},
  {id:'m5-09',paper:5,no:9,section:'Vocabulary',stem:'I lost my wallet. Can you _____ me some money?',options:['borrow','lend','pay','spend'],answer:1,explanation:'Lend means give money to someone temporarily.'},
  {id:'m5-10',paper:5,no:10,section:'Vocabulary',stem:'His uncle is a _____. He teaches students at school.',options:['policeman','teacher','clerk','waiter'],answer:1,explanation:'A person who teaches students at school is a teacher.'},
  {id:'m5-11',paper:5,no:11,section:'Grammar',stem:"Kelly wants to visit her grandparents this weekend, _____ she doesn't have time to go shopping with us.",options:['but','and','or','so'],answer:3,explanation:'Visiting her grandparents causes her not to have time, so is correct.'},
  {id:'m5-12',paper:5,no:12,section:'Grammar',stem:"A: _____ is it?\nB: It's ten to eleven.",options:['What date','What time','How soon','What day'],answer:1,explanation:'“Ten to eleven” tells the time.'},
  {id:'m5-13',paper:5,no:13,section:'Grammar',stem:'This is the most interesting novel that Neil _____.',options:['reads','is reading','will read','has ever read'],answer:3,explanation:'Use has ever + past participle for life experience.'},
  {id:'m5-14',paper:5,no:14,section:'Grammar',stem:'The apartment _____ she lives is near the train station.',options:['which','what','where','who'],answer:2,explanation:'Where introduces the place in which she lives.'},
  {id:'m5-15',paper:5,no:15,section:'Grammar',stem:"Mrs. Jordan will sell her house, _____?",options:['does she','will she',"won't she","won't they"],answer:2,explanation:'A positive statement with will takes the negative tag won’t she.'},
  {id:'m5-16',paper:5,no:16,section:'Grammar',stem:'Jill plans _____ on a picnic this Saturday. We will have fun.',options:['to go','goes','going','go'],answer:0,explanation:'Plan is followed by to + base verb.'},
  {id:'m5-17',paper:5,no:17,section:'Grammar',stem:'_____ is possible for her to pass the exam if she studies harder.',options:['There','It','This','He'],answer:1,explanation:'The pattern is It is possible for someone to + verb.'},
  {id:'m5-18',paper:5,no:18,section:'Grammar',stem:'_____ he is very angry, _____ he can’t speak a word.',options:['Because; so','Even though; but','So; ×','Because; ×'],answer:3,explanation:'Use Because to introduce the cause; do not also use so in the result clause.'},
  {id:'m5-19',paper:5,no:19,section:'Grammar',stem:"The actor was _____ at the news. He didn't believe it.",options:['surprising','surprised','surprise','surprises'],answer:1,explanation:'A person who feels surprise is surprised.'},
  {id:'m5-20',paper:5,no:20,section:'Grammar',stem:"The woman doesn't like one of these dresses. Please show her _____ one.",options:['another','the others','others','other'],answer:0,explanation:'Another + singular noun means one more or a different one.'},
  {id:'m5-21',paper:5,no:21,section:'Cloze-test',stem:'[A]\nDora: What happened, Sean? You look _____.\nSean: I don’t like Sally at all. She is so selfish.\nDora: Why not?\nSean: I asked her for some help this morning, but she turned her nose up at me. She was so impolite that I wanted to shout at her.\nDora: Try to bring yourself to forget it.\nSean: You are right. Thank you.\nDora: No worries.',options:['glad','funny','unhappy','exciting'],answer:2,explanation:'Sean is upset because he thinks Sally was selfish and impolite.'},
  {id:'m5-22',paper:5,no:22,section:'Cloze-test',stem:'[A] She turned her _____ up at me.',options:['nose','mouth','eyes','ears'],answer:0,explanation:'Turn one’s nose up at means to show dislike or disrespect.'},
  {id:'m5-23',paper:5,no:23,section:'Cloze-test',stem:'[A] She was so impolite _____ I wanted to shout at her.',options:['too','that','which','for'],answer:1,explanation:'The pattern is so + adjective + that + result.'},
  {id:'m5-24',paper:5,no:24,section:'Cloze-test',stem:'[A] Try to bring _____ to forget it.',options:['you','your','yours','yourself'],answer:3,explanation:'Bring oneself to means make oneself do something difficult.'},
  {id:'m5-25',paper:5,no:25,section:'Cloze-test',stem:'[B]\nElisa and Frank are classmates. Frank’s neighbor will _____ a Christmas party this Friday. He invites Elisa to go, but she refuses him. Elisa has to visit her uncle. Frank is not happy because the party will be very interesting. He thinks he will have fun.',options:['hold','sell','swim','wash'],answer:0,explanation:'We hold a party.'},
  {id:'m5-26',paper:5,no:26,section:'Cloze-test',stem:'[B] He invites Elisa to go, _____ she refuses him.',options:['and','or','but','so'],answer:2,explanation:'But shows the contrast between the invitation and her refusal.'},
  {id:'m5-27',paper:5,no:27,section:'Cloze-test',stem:'[B] He thinks he will _____.',options:['take off','go over','take a trip','have fun'],answer:3,explanation:'An interesting party is likely to be fun.'},
  {id:'m5-28',paper:5,no:28,section:'Cloze-test',stem:"[C]\nAmanda is a supervisor. She's got a tight schedule today. Amanda has a meeting at nine thirty. She's got to _____ it by ten forty because she has an interview at eleven. Then, she has to drive to the MRT to pick up an important client at twelve thirty. She is really busy, isn’t she?",options:['hold','paint','forget','finish'],answer:3,explanation:'She must finish the meeting before her next appointment.'},
  {id:'m5-29',paper:5,no:29,section:'Cloze-test',stem:'[C] Then, she has to drive to the MRT to _____ an important client at twelve thirty.',options:['pick up','turn off','go through','put on'],answer:0,explanation:'Pick up a person means go and meet or collect that person.'},
  {id:'m5-30',paper:5,no:30,section:'Cloze-test',stem:'[C] She is really _____, isn’t she?',options:['busy','dangerous','delicious','strange'],answer:0,explanation:'Her schedule has many appointments, so she is busy.'},
  {id:'m5-31',paper:5,no:31,section:'Reading',stem:'[A]\nDora: What are you typing?\nKen: I am busy with my history report.\nDora: Wow, you type so fast.\nKen: Yes. I can type 70 words per minute.\nDora: Great. I really envy you. I wish I could type that fast.\nKen: You need to practice more often. It’s not as difficult as you think.\nDora: But I am very busy...\nKen: Please don’t find an excuse.\nDora: OK.\n\nHow many words can Ken type for a minute?',options:['Fifty words.','Seventy words.','Eighty words.','Over one hundred words.'],answer:1,explanation:'Ken says he can type 70 words per minute.'},
  {id:'m5-32',paper:5,no:32,section:'Reading',stem:'[A] What is Ken doing when Dora talks to him?',options:['He is mopping the floor.','He is practicing typing.','He is reading a history book.',"He’s busy with his report."],answer:3,explanation:'Ken says he is busy with his history report.'},
  {id:'m5-33',paper:5,no:33,section:'Reading',stem:'[A] What is true about the dialogue?',options:['Dora is busy with her homework.','Dora can type fast.','She wants to type as fast as Ken does.','Ken finds an excuse.'],answer:2,explanation:'Dora says she wishes she could type that fast.'},
  {id:'m5-34',paper:5,no:34,section:'Reading',table:'<table class="me-table"><tr><th colspan="2">Apartment for Rent<br>Great Location</th></tr><tr><td>Rooms</td><td>Two Bedrooms, 1 Bath</td></tr><tr><td>Transport</td><td>8-min walk to bus station</td></tr><tr><td>Rent</td><td>$9000 a month　$99,000 / yr</td></tr><tr><td>Nearby</td><td>Supermarkets, banks and restaurants</td></tr><tr><td>Included</td><td>A/C, refrigerator, and heat</td></tr><tr><td>Rules</td><td>No Pets · No Smoking · No Parties</td></tr><tr><td>Contact</td><td>Call Kelly at 12345678</td></tr></table>',stem:'Judy would like to rent the house. How might she go to work?',options:['By bus.','By train.','By MRT.','By taxi.'],answer:0,explanation:'The apartment is an eight-minute walk from the bus station.'},
  {id:'m5-35',paper:5,no:35,section:'Reading',table:'<table class="me-table"><tr><th>Apartment for Rent</th></tr><tr><td>Contact: Call Kelly at 12345678</td></tr></table>',stem:'Justin called Kelly this morning. Why did he call her?',options:['He wants to ask her out.','He wants to get a job.','He wants to buy a car.','He wants to rent an apartment.'],answer:3,explanation:'Kelly’s number is listed in an apartment-for-rent advertisement.'},
  {id:'m5-36',paper:5,no:36,section:'Reading',table:'<table class="me-table"><tr><th>Apartment for Rent</th></tr><tr><td>8-min walk to bus station</td></tr><tr><td>Close to supermarkets, banks and restaurants</td></tr><tr><td>No Pets</td></tr></table>',stem:'Which of the sentences is TRUE?',options:['You can keep a pet if you rent the apartment.','The apartment is close to the bus station.','The apartment is near the MRT.','The apartment is not close to a restaurant.'],answer:1,explanation:'It is only an eight-minute walk from the bus station.'},
  {id:'m5-37',paper:5,no:37,section:'Reading',stem:'[C]\nDear Dr. Cage,\nI really need your help.\nI study in junior high school. In fact, I am not happy. I don’t get along well with my classmates because I am too shy and quiet. I only have two friends, Jimmy and Sally. It’s hard for me to express my feelings. Sometimes, they laugh at me. I am so angry that I shout at them.\nMy father is a cook, and my mom is a nurse. They are busy every day; therefore, I seldom talk to them.\nCan you tell me how to solve the problem?\nThank you very much.\nAll the best,\nBeth\n\nWhat does Beth do when her classmates laugh at her?',options:['She shouts at them.','She goes out.','She tells her teacher.','She kicks them.'],answer:0,explanation:'Beth writes that she is so angry that she shouts at them.'},
  {id:'m5-38',paper:5,no:38,section:'Reading',stem:'[C] What does Beth do?',options:['She is a doctor.','She is a student.','She is a writer.','She is a cook.'],answer:1,explanation:'Beth says she studies in junior high school.'},
  {id:'m5-39',paper:5,no:39,section:'Reading',stem:'[C] Why did Beth seldom talk to her father?',options:['He is very serious.','She is afraid of her father.','He is too quiet.','He is very busy.'],answer:3,explanation:'Beth says her parents are busy every day.'},
  {id:'m5-40',paper:5,no:40,section:'Reading',stem:'[C] Which of the sentences is TRUE?',options:["Beth doesn't have any friends in class.",'Dr. Cage needs some help.','Beth is worried about her school life.',"Beth's mother is a cook."],answer:2,explanation:'Beth says she is unhappy and has problems with classmates at school.'}
];
